import org.yapyap.protocol.DeviceType
import org.yapyap.routing.router.Router

public interface OrchestratorRuntime {
    public val messaging: MessagingService
    public val config: ConfigService

    /** Bootstrap / onboarding handshake (scaffolding; bodies land with sprint 4). */
    public val onboarding: OnboardingService

    /** Read-only roster: accounts, devices, per-account presence. */
    public val identity: IdentityService

    /** Chat list, headers, and room creation. */
    public val rooms: RoomService

    /** Admin-gated global-event mutations. */
    public val admin: AdminService

    /** Self-service: own devices and account. */
    public val account: AccountService
    // sync added in a later sprint
}

internal class DefaultOrchestratorRuntime(
    private val dagEngine: DagEngine,
    private val router: Router,
    private val pipeline: InboundMessagePipeline,
    private val database: YapYapDatabase,
    private val identityResolver: IdentityResolver,
    private val messageLimits: StateFlow<MessageLimits>,
    private val configStore: ConfigStore,
    private val onboardingProvider: OnboardingProvider,
    private val identityKeyRepository: IdentityKeyRepository,
    private val identityProvisioning: IdentityProvisioning,
    private val cryptoProvider: CryptoProvider,
    private val globalEventProjector: GlobalEventProjector,
    private val roomEventProjector: RoomEventProjector,
    private val roomRepository: RoomRepository,
    private val localDeviceType: DeviceType,
) : OrchestratorRuntime {

    private lateinit var _messaging: DefaultMessagingService
    override val messaging: MessagingService get() = _messaging

    private lateinit var _config: DefaultConfigService
    override val config: ConfigService get() = _config

    private lateinit var _onboarding: DefaultOnboardingService
    override val onboarding: OnboardingService get() = _onboarding

    private lateinit var _rooms: DefaultRoomService
    override val rooms: RoomService get() = _rooms

    private lateinit var _identity: DefaultIdentityService
    override val identity: IdentityService get() = _identity

    private lateinit var _admin: DefaultAdminService
    override val admin: AdminService get() = _admin

    private lateinit var _account: DefaultAccountService
    override val account: AccountService get() = _account

    fun start(scope: CoroutineScope) {
        _messaging = DefaultMessagingService(
            dagEngine = dagEngine,
            router = router,
            pipeline = pipeline,
            roomRepository = roomRepository,
            messageRepository = DefaultMessageRepository(database),
            causalHoldRepository = DefaultCausalHoldRepository(database),
            identityResolver = identityResolver,
            messageLimits = messageLimits,
            orchestratorConfig = configStore.orchestratorConfig,
        )
        _messaging.start(scope)

        _onboarding = DefaultOnboardingService(
            provider = onboardingProvider,
            router = router,
            identityResolver = identityResolver,
            messageRepository = DefaultMessageRepository(database),
            cryptoProvider = cryptoProvider,
            localDeviceType = localDeviceType,
            projector = globalEventProjector,
        )

        _config = DefaultConfigService(configStore)
        _config.start(scope)

        _rooms = DefaultRoomService(
            projector = roomEventProjector,
            roomRepository = roomRepository,
            identityKeyRepository = identityKeyRepository,
            identityResolver = identityResolver,
        )
        _rooms.start(scope)

        // Stateless (no StateFlow of its own, nothing to collect): constructed only,
        // no start/stop.
        _account = DefaultAccountService(
            projector = globalEventProjector,
            identityResolver = identityResolver,
            identityKeyRepository = identityKeyRepository,
            identityProvisioning = identityProvisioning,
            onboardingState = onboardingProvider.state,
        )

        // Stateful in one field (the live localIsAdmin flag off the projector's
        // stateChanges): needs start/stop like the room service.
        _admin = DefaultAdminService(
            projector = globalEventProjector,
            identityResolver = identityResolver,
            identityKeyRepository = identityKeyRepository,
            onboardingState = onboardingProvider.state,
        )
        _admin.start(scope)

        // Read-only roster: rows + router presence + fold events. All deps are
        // already constructor params — no new wiring.
        _identity = DefaultIdentityService(
            identityKeyRepository = identityKeyRepository,
            router = router,
            projector = globalEventProjector,
            orchestratorConfig = configStore.orchestratorConfig,
        )
        _identity.start(scope)
    }

    suspend fun stop() {
        _messaging.stop()
        _rooms.stop()
        _admin.stop()
        _identity.stop()
    }
}

package org.yapyap.orchestrator.runtime.message

import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.StateFlow
import org.yapyap.protocol.AccountId
import org.yapyap.protocol.RoomId
import kotlin.uuid.Uuid

public interface MessagingService {

    /** Max text length in bytes that [sendMessage] will accept. Derived from transport limits. */
    public val maxTextMessageBytes: Int

    public val incomingMessageEvents: Flow<IncomingMessageEvent>

    /**
     * Accounts currently typing per room (roomId → typing accounts), derived from received
     * typing indicators with an idle timeout of ~2x the sender's announced cadence.
     * Backend for the GUI "typing…" display. The local account's own announcements
     * (e.g. from another device) are excluded.
     */
    public val typingState: StateFlow<Map<RoomId, Set<AccountId>>>

    /** Outbound: append to local DAG (refused up front on policy violations),
     *  then fan out to room members. The message is durable once [SendMessageResult.Sent] returns. */
    public suspend fun sendMessage(roomId: RoomId, message: Message): SendMessageResult

    /** Lookup of a single message by id, mapped to its GUI display item (null when unknown or not displayable). */
    public suspend fun getMessage(messageId: Uuid): MessageDisplayItem?

    /**
     * Open a room for viewing. Returns a paginated window.
     * Caller must call [RoomMessageWindow.close] when navigating away.
     */
    public suspend fun openRoom(roomId: RoomId, initialPageSize: Int = 100): RoomMessageWindow

    /**
     * Latest visible message of [roomId] for the room list (docs/room events.md
     * §3): walks newest→oldest over one page and returns the first non-`REJECTED`
     * displayable message whose author passes the render policy. Null when no
     * visible message exists (empty room, pre-fold room, deferred authors,
     * all-hidden). The returned item is unformatted — the GUI decides how to
     * render it. The GUI re-pulls this on [incomingMessageEvents]; the event
     * itself carries no content, so hidden messages never leak through the
     * preview path.
     */
    public suspend fun roomPreview(roomId: RoomId, scanLimit: Int = 100): RoomPreview?

    /**
     * Start/stop announcing that the local user is typing in [roomId]. While active, the
     * service announces to the room's members every
     * `typingIndicatorInterval`. The GUI calls this on typing-state
     * changes (e.g. first keystroke after an idle pause / idle timeout); announcements are
     * periodic heartbeats, so there is no explicit "stopped typing" wire message.
     */
    public suspend fun setTyping(roomId: RoomId, isTyping: Boolean)
}
package org.yapyap.orchestrator.runtime.message

import kotlinx.coroutines.flow.StateFlow
import org.yapyap.protocol.AccountId
import org.yapyap.protocol.RoomId
import kotlin.time.Instant
import kotlin.uuid.Uuid

public sealed interface MessageDisplayItem {
    /** Stable identity used as a Compose list key and for targeted removal (e.g. on rejection). */
    public val messageId: Uuid
    public val accountId: AccountId
    public val timestamp: Instant

    public data class Text(
        override val messageId: Uuid,
        override val accountId: AccountId,
        override val timestamp: Instant,
        val text: String,
    ) : MessageDisplayItem

    public data class File(
        override val messageId: Uuid,
        override val accountId: AccountId,
        override val timestamp: Instant,
        val fileId: String,
        val fileName: String,
        val fileSize: Long,
    ) : MessageDisplayItem

    public data class Gap(
        override val messageId: Uuid,
        override val accountId: AccountId,
        override val timestamp: Instant,
        val missingPrevIds: List<Uuid>,
    ) : MessageDisplayItem
}

public data class Message(
    val content: String,
)

/**
 * "Something new in this room" signal carrying the policy-vetted
 * [MessageDisplayItem], unformatted — presentation (truncation, "sent a file"
 * labels) is the GUI's call. The emit path is gated on the renderable check
 * (docs/room events.md §3, enforced in SQL), so hidden messages and
 * non-displayable payloads never ride this event; [org.yapyap.orchestrator.runtime.message.MessagingService.roomPreview]
 * remains the source of truth for initial population and re-pulls (e.g.
 * after a REJECTED drop).
 */
public data class IncomingMessageEvent(
    val roomId: RoomId,
    val senderAccountId: AccountId,
    val item: MessageDisplayItem,
)

/**
 * Latest *visible* message of a room (docs/room events.md §3): the newest row
 * of the renderable page query — non-`REJECTED` and inside the removal boundary —
 * that maps to a [MessageDisplayItem]. Null when the room holds no visible message
 * (empty, pre-fold, or all-hidden).
 *
 * The item is carried unformatted: truncation, "sent a file" labels and any
 * other presentation decisions are GUI concerns.
 */
public data class RoomPreview(
    val messageId: Uuid,
    val senderAccountId: AccountId,
    val timestamp: Instant,
    val item: MessageDisplayItem,
)

/**
 * A paginated window into a room's messages.
 * Created by [MessagingService.openRoom]; caller must [close] when done.
 */
public interface RoomMessageWindow {
    /** Current loaded messages (oldest→newest). Bind this to the GUI list. */
    public val displayItems: StateFlow<List<MessageDisplayItem>>

    /** Whether older messages exist beyond the currently loaded window. */
    public val hasMoreOlder: StateFlow<Boolean>

    /**
     * Load the next page of older messages (prepended to [displayItems]).
     * @return Number of messages loaded (0 means no more older messages).
     */
    public suspend fun loadOlder(pageSize: Int = 50): Int

    /** Release this window and unsubscribe from updates. */
    public suspend fun close()
}

/** Outcome of the GUI-facing text-send flow. Domain refusals are values;
 *  infrastructure failures (transport, storage) still throw. */
public sealed interface SendMessageResult {
    /** Appended to the room DAG and fanned out. [fanout] is a send-time
     *  reachability snapshot — advisory, never an error state. */
    public data class Sent(val fanout: FanoutReport) : SendMessageResult

    /** Refused before any write — nothing appended, nothing sent. */
    public data class Refused(val reason: SendRefusal) : SendMessageResult
}

public sealed interface SendRefusal {
    /** Local account holds a committed REMOVED row for the room. */
    public data object NotMember : SendRefusal

    /** Text exceeds [MessagingService.maxTextMessageBytes]. */
    public data object TooLarge : SendRefusal

    /** Room frontier unchainable — still syncing. */
    public data object HistoryIncomplete : SendRefusal
}

/**
 * Reachability snapshot at send time, per *member account* (devices collapsed;
 * the orchestrator never deals in peer ids).
 *
 * The local account is excluded: own devices converge via the pull path
 * regardless, and the user's mental model of delivery is other members.
 *
 * [membersPullOnly] covers every no-live-push situation — deferred sessions,
 * no known devices, failed pushes — because in all of them the pull path
 * (ping frontiers + sync) is the delivery path. "Pending" would overpromise
 * for the no-devices case; the GUI may still render it as "pending sync".
 */
public data class FanoutReport(
    /** Other member accounts fanned out to. */
    val membersTotal: Int,
    /** Accounts with at least one device queued to the outbox now. */
    val membersQueued: Int,
    /** Accounts with no live push path — they pick the message up via sync. */
    val membersPullOnly: Int,
)

package org.yapyap.orchestrator.runtime.room

import kotlinx.coroutines.flow.StateFlow
import org.yapyap.protocol.AccountId
import org.yapyap.protocol.RoomId

/**
 * GUI-facing chat management: room list, room headers, room creation, and room
 * membership ops. Creation and membership changes publish real room-DAG events
 * (genesis + MemberAdd/MemberRemove/AddAdmin/RemoveAdmin) via the room-event
 * projector's publish path; the fold (not the service) decides what lands.
 */
public interface RoomService {
    /**
     * Rooms the local account belongs to (GLOBAL excluded; provisional UNKNOWN
     * rooms excluded until their genesis folds). Projection order —
     * message-derived ordering (e.g. by last activity) is composed by the GUI
     * from `MessagingService.roomPreview`, which owns all message reads.
     */
    public val rooms: StateFlow<List<RoomDetails>>

    /** Chat-header detail, or null for unknown rooms. */
    public suspend fun room(roomId: RoomId): RoomDetails?

    /**
     * Create a direct or group chat with [members]. Publishes the `RoomCreated`
